WITH prev_events AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM device_readings), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), islands AS (SELECT id, device_code, reading_ts, temp_c, humidity, firmware, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT device_code, DATE_TRUNC('DAY', reading_ts) AS activity_day, COUNT_IF(device_code = 'DV-03') AS dv_03_events, SUM(humidity) FILTER (WHERE device_code = 'DV-04') AS dv_04_total_humidity, SUM(CASE WHEN device_code = 'DV-04' THEN temp_c ELSE 0 END) AS dv_04_temp_c, AVG(session_id) AS avg_session_id FROM islands GROUP BY device_code, DATE_TRUNC('DAY', reading_ts);
